#elif ROSE_ALLOC_MEMSET == 2
    memset(((char*)object) + ROSE_ALLOC_MEMSET_OFFSET, 0x00, sizeof(SgFunctionDeclaration) - ROSE_ALLOC_MEMSET_OFFSET * sizeof(char*));
#elif ROSE_ALLOC_MEMSET == 3
    memset(((char*)object) + ROSE_ALLOC_MEMSET_OFFSET, 0xBB, sizeof(SgFunctionDeclaration) - ROSE_ALLOC_MEMSET_OFFSET * sizeof(char*));
